"""X-MFG-35 in-house BMED stack (A-M-170). NaOH production from the solver (one NaOH per HCl, AQS-PAR-001); current I = n F / CE through
every triplet in series; stack current = j x A; triplets = n F / (CE j A); stacks of at most N triplets, plus one spare stack (redundancy rule).
Implied triplet voltage from the published SEC: V = SEC x M_NaOH x CE / F. Run: python3 -m flow_graph.param.bmed_stack [--write]"""
import json, math, os, sys
from . import drivers as DR, solver
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
F = 96485.0
def design():
    d, g, s = solver.solve(); v = lambda k: DR.val(d, k)
    n = s['bmed']['base_kg_d']/0.039997/86400                                     # mol/s NaOH
    I = v('bmed_j_A_m2')*v('bmed_cell_area_m2'); N = math.ceil(n*F/(v('bmed_CE')*I))
    ns = math.ceil(N/v('bmed_cells_per_stack_max')); per = math.ceil(N/ns)
    V = v('bmed_sec_kWh_per_kg_base')*3.6e6*0.039997*v('bmed_CE')/F
    return dict(NaOH_kg_d=s['bmed']['base_kg_d'], mol_s=n, I_stack_A=I, triplets=N, stacks=ns, spare_stacks=1, triplets_per_stack=per, membrane_m2=3*N*v('bmed_cell_area_m2'),
                V_triplet_implied=V, kW=N*I*V/1000, frame='PP frames 300 x 300 mm, 0.8 mm PE mesh spacers, Ti/MMO anode and 316L/Ni cathode end plates, PP end plates with tie rods')
def main():
    r = design(); print(json.dumps(r, default=float))
    if '--write' in sys.argv:
        md = ['# BMED stack', '', 'Document number: AQS-DUTY-068', 'Revision: A', 'Date: 2026-10-15', 'Authority: AQS-PLAN-007 X-MFG-35. Generated by `flow_graph/param/bmed_stack.py`. Study. A-M-170.', '',
              f"NaOH {r['NaOH_kg_d']:.2f} kg/d ({r['mol_s']*1000:.2f} mmol/s) at 200 A/m2 and CE 0.80 (EDBM_PILOT_2023) on 0.04 m2 cells: stack current {r['I_stack_A']:.1f} A, {r['triplets']} triplets in {r['stacks']} stacks of {r['triplets_per_stack']}, plus {r['spare_stacks']} spare stack; {r['membrane_m2']:.1f} m2 of membrane (bipolar, anion, cation).",
              '', f"Implied triplet voltage from the SEC on the graph (6.7 kWh/kg, EDBM_WHEY_2021, 2 M product): {r['V_triplet_implied']:.1f} V, against 1.4 kWh/kg (1.7 V per triplet) in EDBM_PILOT_2023 at lower product strength. The graph energy ({r['kW']:.1f} kW here) stays on the published 2 M figure until the stack polarisation test sets it (A-M-170).",
              '', 'Construction: ' + r['frame'] + '.']
        open(os.path.join(ROOT, 'docs-authority/sizing/BMED_STACK.md'), 'w').write('\n'.join(md) + '\n')
if __name__ == '__main__': main()
